{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
  <meta name="description" content="Gentle aromatherapy events and sessions in {{CITY}}, {{STATE}}. Practical blends and safety-first guidance.">
</head>
<body>
  <div class="site" id="site">
    <header class="site-header">
      <div class="brand"><a href="/">{{BUSINESS_NAME}}</a></div>
      <nav class="nav">
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends &amp; Notes</a>
        <a href="shop.html">Apothecary</a>
        <a href="about.html">Story</a>
        <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" id="navToggle" aria-label="Menu">☰</button>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="pattern" aria-hidden="true"></div>
        <div class="hero-inner">
          <h1 class="title">A small tide of scent. A steady hush of balance.</h1>
          <p class="subtitle">{{TAGLINE}}</p>
          <div class="hero-ctas">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn btn-ghost" href="services.html">Explore sessions</a>
          </div>
        </div>
        <svg class="ripple" viewBox="0 0 800 200" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#e8f6f0"/><stop offset="1" stop-color="#f3efe8"/></linearGradient></defs><path d="M0 120 C200 160 400 80 800 120 L800 200 L0 200 Z" fill="url(#g1)"/></svg>
      </section>

      <section id="diagnostic" class="diagnostic">
        <h2>Find your fragrant compass</h2>
        <p class="lead">A short safety-forward guide to choose scents that suit your day. No promises — just careful, aromatic choices.</p>
        <form id="diagForm" class="diag-form">
          <label>I'm seeking: <select name="goal"><option>calm focus</option><option>gentle sleep</option><option>uplift</option><option>ritual relaxation</option></select></label>
          <label>Scent strength: <select name="strength"><option>subtle</option><option>moderate</option><option>lush</option></select></label>
          <button type="submit" class="btn">Suggest a gentle blend</button>
          <div id="diagResult" class="diag-result" aria-live="polite"></div>
        </form>
      </section>

      <section id="plan" class="plan">
        <h2>Seasonal events &amp; series</h2>
        <p class="lead">Small-group sessions and a repeating series of practices led by {{PRACTITIONER_NAME}}. Safety and slow breath first.</p>
        <ul class="events">
          <li><strong>Intro to Home Diffusion</strong><span class="meta">Monthly • 90 min • Light blending</span></li>
          <li><strong>Evening Rituals</strong><span class="meta">Weekly series • 6 sessions</span></li>
          <li><strong>Blend Lab: Citrus &amp; Herbs</strong><span class="meta">One-day workshop • Kit included</span></li>
        </ul>
        <a class="btn btn-secondary" href="book.html">See schedule &amp; reserve</a>
      </section>

      <section id="micro_habits" class="micro-habits">
        <h2>Micro-habits: a scent a day</h2>
        <p class="lead">Tiny practices that fit a pocket of your day. Track one week at a time.</p>
        <ul class="habit-list">
          <li><label><input type="checkbox" data-habit="breathe" /> 3 deep breaths with a single drop of {{FAVORITE_BLEND}} on a cloth (patch test first).</label></li>
          <li><label><input type="checkbox" data-habit="desk-diffuse" /> 10-min desk diffusion with a mild citrus-mint rotation.</label></li>
          <li><label><input type="checkbox" data-habit="evening-rinse" /> Warm shower steam with a lavender spritz (avoid direct skin contact).</label></li>
        </ul>
        <button id="saveHabits" class="btn">Save habits</button>
      </section>

      <section id="pricing" class="pricing">
        <h2>Care plans &amp; pricing</h2>
        <div class="price-grid">
          <article class="card"><h3>Intro Session</h3><p class="amount">$65</p><p class="desc">60-min safety-focused consultation + light blending demo.</p></article>
          <article class="card"><h3>Series Pass</h3><p class="amount">$240</p><p class="desc">Six-session series for gentle practice and guidance.</p></article>
          <article class="card"><h3>Event Kit</h3><p class="amount">$35</p><p class="desc">Hands-on kit for workshops (supplies &amp; notes).</p></article>
        </div>
        <p class="note">All sessions emphasize dilution, patch testing, and pet/pregnancy precautions. No medical claims.</p>
      </section>

      <section id="cta" class="final-cta">
        <h2>Ready for a quiet ritual?</h2>
        <p>Book a place in the next series or request a tailored gentle blend.</p>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="tiny">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </section>
    </main>

    <footer class="site-footer">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}} • <a href="contact.html">Contact</a></p>
    </footer>
  </div>
  <script src="assets/js/main.js"></script>
</body>
</html>"} 
