{"path":"assets/css/styles.css","content":"/* Zen minimal aromatherapy stylesheet */
:root{--bg:#fbfbf8;--muted:#667071;--accent:#7fbfa3;--accent-2:#f1d6b4;--card:#ffffff;--radius:12px;--glass:rgba(255,255,255,0.6)}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:#233033;background:linear-gradient(180deg,var(--bg),#fff);margin:0}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;border-bottom:1px solid rgba(34,48,51,0.06);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.35));backdrop-filter:blur(4px);z-index:10}
.brand a{font-weight:600;color:var(--accent);text-decoration:none}
.nav{display:flex;gap:16px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),#a9d8c6);color:#07312b;font-weight:600}
.nav-toggle{display:none;background:none;border:0;font-size:20px}
.hero{position:relative;overflow:hidden;padding:56px 20px 30px;display:flex;align-items:flex-end;min-height:38vh}
.pattern{position:absolute;inset:0;background-image:url('../img/pattern.svg');background-repeat:repeat;background-size:260px;opacity:0.95;mix-blend-mode:multiply}
.hero-inner{position:relative;max-width:980px;margin:0 auto;padding:40px;text-align:center}
.title{font-size:clamp(22px,4.6vw,40px);margin:0 0 10px;color:#0b2b26;font-weight:700}
.subtitle{color:var(--muted);margin:0 0 20px}
.hero-ctas{display:inline-flex;gap:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid transparent;cursor:pointer}
.btn-primary{background:linear-gradient(90deg,var(--accent),#9bcdb6);color:#062e26;font-weight:700}
.btn-ghost{background:transparent;border:1px solid rgba(6,46,38,0.06);color:var(--muted)}
.ripple{position:absolute;left:0;right:0;bottom:0;height:90px}
main{max-width:980px;margin:28px auto;padding:0 20px}
section{margin:32px 0;padding:24px;border-radius:14px;background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.4));box-shadow:0 6px 18px rgba(16,22,20,0.04);backdrop-filter:blur(6px)}
h2{margin:0 0 10px;color:#12332d}
.lead{color:var(--muted);margin:0 0 16px}
.diag-form label{display:block;margin:10px 0}
.diag-result{margin-top:12px;color:#0a3a33}
.events{list-style:none;padding:0;margin:0 0 12px}
.events li{display:flex;justify-content:space-between;padding:12px 8px;border-radius:10px;background:transparent}
.meta{color:var(--muted);font-size:13px}
.price-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px}
.card{padding:14px;border-radius:12px;background:linear-gradient(180deg,#fff,#fbfdfb);border:1px solid rgba(6,46,38,0.03)}
.amount{font-weight:700;color:#0d3b31;font-size:20px;margin:8px 0}
.note{font-size:13px;color:var(--muted);margin-top:10px}
.habit-list{list-style:none;padding:0;margin:0}
.habit-list li{padding:8px 0}
.final-cta{text-align:center}
.tiny{font-size:13px;color:var(--muted)}
.site-footer{padding:18px;text-align:center;color:var(--muted);font-size:14px}
@media (max-width:720px){
  .nav a{display:none}
  .nav-toggle{display:block}
  .hero-inner{padding:28px}
}
/* subtle motion */
.ripple path{transform-origin:center;animation:float 8s ease-in-out infinite}
@keyframes float{0%{transform:translateY(0)}50%{transform:translateY(-8px)}100%{transform:translateY(0)}}
/* focus states */
:focus{outline:2px dashed rgba(123,183,160,0.32);outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple site interactions: nav toggle, diagnostic suggestion, habit save
  var navToggle=document.getElementById('navToggle');
  if(navToggle){navToggle.addEventListener('click',function(){document.body.classList.toggle('nav-open');})}

  // Year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Diagnostic form
  var diag=document.getElementById('diagForm');
  if(diag){diag.addEventListener('submit',function(e){e.preventDefault();var form=new FormData(diag);var goal=form.get('goal');var strength=form.get('strength');var note='Suggested: a gentle blend with light top-notes and soft base notes. Try low dilution and patch-test first.'; if(goal==='gentle sleep'){note='Suggested: calming middle-notes with subtle base — use in a diffuser at low intensity and always patch-test.'} else if(goal==='uplift'){note='Suggested: bright top-notes (citrus/herb) used sparingly; avoid direct skin contact.'}
    var el=document.getElementById('diagResult'); if(el){el.textContent=note}
  })}

  // Habits persistence
  var saveBtn=document.getElementById('saveHabits');
  var checkboxes=document.querySelectorAll('.habit-list input[type=checkbox]');
  function loadHabits(){checkboxes.forEach(function(cb){try{cb.checked=localStorage.getItem('habit:'+cb.dataset.habit)==='1'}catch(e){}})}
  function saveHabits(){checkboxes.forEach(function(cb){try{localStorage.setItem('habit:'+cb.dataset.habit,cb.checked? '1':'0')}catch(e){}}); if(saveBtn){saveBtn.textContent='Saved'} setTimeout(function(){if(saveBtn)saveBtn.textContent='Save habits'},1200)}
  if(saveBtn){saveBtn.addEventListener('click',saveHabits)}; loadHabits();

  // Small accessibility enhancement: close nav when clicking outside on mobile
  document.addEventListener('click',function(e){if(document.body.classList.contains('nav-open') && !e.target.closest('.nav') && !e.target.closest('#navToggle')){document.body.classList.remove('nav-open')}})
})();"} 
